name: PR Issue Link Check
on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

jobs:
  check-pr-issue-link:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Issue Link
        id: check
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const prTitle = pr.title;
            const prBody = pr.body || '';

            // Get all commits in the PR
            const { data: commits } = await github.rest.pulls.listCommits({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const commitMessages = commits.map(commit => commit.commit.message);

            // Pattern to match issue references (Fixes #123, Closes #456, Resolves #789)
            const issuePattern = /(?:fixes|closes|resolves)\s+#(\d+)/gi;

            let issueNumbers = [];
            let foundInTitle = false;
            let foundInBody = false;
            let foundInCommits = false;

            // Check title
            const titleMatches = prTitle.match(issuePattern);
            if (titleMatches) {
              issueNumbers = issueNumbers.concat(titleMatches.map(match => match.match(/\d+/)[0]));
              foundInTitle = true;
            }

            // Check body
            const bodyMatches = prBody.match(issuePattern);
            if (bodyMatches) {
              issueNumbers = issueNumbers.concat(bodyMatches.map(match => match.match(/\d+/)[0]));
              foundInBody = true;
            }

            // Check commit messages
            for (const message of commitMessages) {
              const commitMatches = message.match(issuePattern);
              if (commitMatches) {
                issueNumbers = issueNumbers.concat(commitMatches.map(match => match.match(/\d+/)[0]));
                foundInCommits = true;
              }
            }

            // Remove duplicates
            issueNumbers = [...new Set(issueNumbers)];

            if (issueNumbers.length === 0) {
              core.setFailed('Pull request must reference at least one issue. Please use "Fixes #123", "Closes #456", or "Resolves #789" format.');
              return;
            }

            // Validate each issue exists
            for (const issueNumber of issueNumbers) {
              try {
                await github.rest.issues.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issueNumber)
                });
              } catch (error) {
                if (error.status === 404) {
                  core.setFailed(`Referenced issue #${issueNumber} does not exist.`);
                  return;
                } else {
                  throw error;
                }
              }
            }

            // If we get here, all validations passed
            console.log(`Validated PR title: ${foundInTitle ? '✓' : '✗'} Body: ${foundInBody ? '✓' : '✗'} Commits: ${foundInCommits ? '✓' : '✗'}`);
            console.log(`Found issues: ${issueNumbers.join(', ')}`);
